  "exports.eyebrow": "Data",
  "exports.title": "Ekspor & serep",
  "exports.subtitleStart": "Undhuhan tansah kawates dhateng",
  "exports.subtitleRest": ". Saben berkas dipunlabeli kanthi nama bisnis lan tanggal damelipun.",
  "exports.createBusinessFirst": "Damel bisnis rumiyin — ekspor kagungan bisnis, sanès aplikasi.",
  "exports.lockedTitle": "Ekspor CSV lan Excel minangka fitur Business",
  "exports.lockedDesc": "Papan makarya Panjenengan ing paket Essentials. Business nambah ekspor CSV lan Excel, valuasi stok, produk lan staf tanpa wates, pemasok, tumbas, lan bundel.",
  "exports.seeBusiness": "Priksa punapa ingkang kalebet ing Business",
  "exports.whatTheseAre": "Punapa berkas punika",
  "exports.about1": "Saben set data dhateng minangka CSV utawi buku makarya Excel saestu (.xlsx) — buku makarya inventaris jangkep namung Excel, kanthi satunggal lembar saben set data. Berkas CSV mbikak ing Excel, Numbers, Google Sheets, lan kathah aplikasi stok. Teks UTF-8, koma ingkang dipunkutip, jeda baris ing cathetan, lan nol ngajeng ing kode sedaya dipunjagi, lan sel ingkang wiwit kados rumus dipunnetralaken supados spreadsheet mbikak minangka teks.",
  "exports.about2": "Ing berkas Excel, SKU, UPC, ISBN, lan barcode minangka sel teks — mboten nate notasi ilmiah lan mboten nate nol ingkang dipunpotong — kanthi jembar kolom, saringan header, lan format mata uang utawi cacah ingkang dipunterapaken. Buku makarya inventaris jangkep njagi produk, tataran stok, lokasi, lan obahan ing lembar kapisah.",
  "exports.about3": "Ekspor ingkang ageng sanget mandheg ing 20.000 larik saben set data — nalika punika kedadosan nama berkas ngandharaken (truncated-20000), dados berkas saperangan mboten nate katon jangkep.",
  "exports.about4": "Serep minangka potret data Panjenengan, sanès pamulihan satunggal tutul. Mulihaken minangka pakaryan manual, priksa rumiyin, dados jagi berkas kanthi aman — mboten wonten ing aplikasi ingkang saged ngripta malih bisnis ingkang kabusak saking serep punika. Kode aplikasi lan serep platform Base44 dipunurus kapisah saking berkas punika.",
  "exports.about5": "Foto lan lampiran kadhaptar minangka tautan kasimpenipun — berkas gambar piyambak mboten dipunkemas ing undhuhan.",
  "exports.backupTitle": "Serep jangkep",
  "exports.backupDesc": "Satunggal berkas kanthi produk, lokasi, tataran stok, buku obahan jangkep, pemasok, tumbas, pesanan, wangsulan, etangan, lan dhaptar bisnis punika — wimbuh pangaturan profilipun. Simpen ing papan ingkang Panjenengan kontrol.",
  "exports.backupIncludes1": "Produk, kode, bea, lan cathetan",
  "exports.backupIncludes2": "Lokasi lan cacah saben lokasi",
  "exports.backupIncludes3": "Saben obahan, kanthi pelaku lan wekdal",
  "exports.backupIncludes4": "Tumbas, pesanan, wangsulan, lan etangan",
