  "print.templateIsBusiness": "{label} minangka fitur Business",
  "print.supplierBlockedDesc": "Dokumen pemasok sesarengan kaliyan paket Business — pemasok, tumbas, lan pesanan tumbas. Sedaya ingkang Panjenengan gadhahi sapunika tetep makarya.",
  "print.seeBusiness": "Priksa punapa ingkang kalebet ing Business",
  "print.nothingToPrint": "Dereng wonten ingkang dipuncithak",
  "print.pickOrderHint": "Pilih pesanan tumbas saking dhaptar kangge pratinjau dokumen.",
  "print.pickCustomerOrderHint": "Pilih pesanan pelanggan saking dhaptar kangge pratinjau dokumen.",
  "print.pickReturnHint": "Pilih wangsulan ingkang kacathet saking dhaptar kangge pratinjau dokumen.",
  "print.chooseStyleHint": "Pilih gaya, lajeng pilih produk saking dhaptar. Pratinjau ningali persis punapa ingkang medal saking printer.",
  "print.howToReach": "Kados pundi dumugi printer Panjenengan",
  "print.howIntro": "Aplikasi punika nyambung dhateng printer ingkang sampun Panjenengan gadhahi — sanès printer piyambak. Wonten sekawan cara kangge dumugi satunggal, lan label kacithak ing kekalih paket lumantar cara punapa kemawon. Slip kemasan, pesanan tumbas, dokumen pemasok, lan laporan namung Business, cara sambungan punapa kemawon.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Saking kaca punika, ing Chrome utawi Edge desktop lan ing Chrome Android: pilih printer label Panjenengan lan label langsung dhateng ngriku. Mboten saged ing Safari iOS — ing iPhone, nyithak Bluetooth dhateng kaliyan aplikasi seluler kemawon. Printer ingkang namung mangertos basa Zebra ZPL utawi basa Brother piyambak mboten badhé mangertos label ingkang dipunkintun kaca punika; punika dipunpriksa adhedhasar printer saestu sadèrèngipun dipunsebut makarya.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Pasang printer ing Wi-Fi toko Panjenengan, lajeng ginakaken tombol Cithak — nyithak lumantar printer ingkang kapasang ing komputer punika, lumantar jaringan toko. Ing iPhone, AirPrint sampun kapasang: printer AirPrint ing Wi-Fi ingkang sami langsung katon ing lembar cithak, tanpa kabel lan tanpa aplikasi, lan aplikasi mboten mbetahaken kode mirunggan AirPrint. Printer kedah nyengkuyung AirPrint (kathah ingkang enggal nyengkuyung) lan ponsel lan printer kedah ing Wi-Fi ingkang sami.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Sambungaken printer dhateng jaringan toko Panjenengan kanthi kabel Ethernet, pasang ing komputer, lan cithak lumantar tombol Cithak. Ethernet minangka jalur desktop lan komputer — iPhone mboten ngginakaken kabel Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Colokaken printer dhateng komputer kanthi kabelipun lan ginakaken tombol Cithak — nyithak lumantar printer ingkang kapasang ing ngriku. Ing ponsel Android kanthi kabel USB OTG, tombol USB ing nginggil punika langsung guneman dhateng printer. iPhone mboten saged nyithak lumantar USB langsung — mboten wonten WebUSB ing ngriku — dados ginakaken Wi-Fi / AirPrint, utawi Bluetooth saking aplikasi seluler.",
  "print.howCordsLead": "Kabel taksih nglayani iPhone, satunggal langkah langkung tebih.",
  "print.howCordsBody": "Printer USB ingkang kaccolok dhateng komputer toko, utawi printer Ethernet ingkang kasambung dhateng jaringan, katon ing iPhone Panjenengan lumantar Wi-Fi toko (AirPrint / printer ingkang dipunbagi) — kabel manggenaken printer ing jaringan kanthi bakuh, lan ponsel dumugi kanthi nirkabel.",
  "print.howOfflineLead": "Menawi internet pedhot,",
  "print.howOfflineBody": "label lan dokumen ingkang sampun wonten ing kaca punika taksih kacithak — tombol Cithak, PDF Label, Bluetooth, lan USB mboten mbetahaken sambungan. Ingkang mbetahaken internet inggih punika ngemot kaca lan produkipun ing wiwitan. Mode luring jangkep (makarya ing aplikasi tanpa sambungan babar pisan) minangka riptaan kapisah ingkang langkung ageng lan mboten dipunaku ing ngriki.",
