  "settings.cancelSubscription": "Batalaken Langganan",
  "settings.cancelTerms.appleLink": "Pituduh pambatalan Apple",
  "settings.cancelTerms.googlePlayLink": "Pituduh pambatalan Google Play",
  "settings.cancelTerms.graceTitle": "Sasampunipun mangsa bayar Panjenengan pungkasan — sihu 15 dinten, lajeng pambusakan:",
  "settings.cancelTerms.intro": "Punika ketentuan kangge langganan Luminous StockHaven ingkang mbayar. Tagihan langganan situs web lumantar Stripe. Panjenengan saged mbatalaken langganan Panjenengan piyambak kapan kemawon ngginakaken tombol Batalaken Langganan ing ngandhap punika — mboten prelu sarujuk staf. Panyuwunan pambatalan lan wangsulan dana ugi saged dipunurus lumantar kontak panyengkuyung pelanggan resmi, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Panjenengan saged mbatalaken langganan Panjenengan piyambak kapan kemawon. Mboten prelu sarujuk staf. Pembaruan mangsa ngajeng namung mandheg sasampunipun panyedhiya tagihan mesthiaken pambatalan.",
  "settings.cancelTerms.noApprovalTitle": "Batalaken tanpa sarujuk:",
  "settings.cancelTerms.paymentBody": "Kangge uji coba bayar, uji coba pitung dinten mbetahaken cara pembayaran nalika ndhaptar. Kajawi dipumbatalaken salebeting titi wanci pambatalan uji coba ingkang lumaku, paket wulanan ingkang kapilih badhé dipuntagih kanthi otomatis sasampunipun uji coba. Regi, tanggal tagihan sepisan, lan titi wanci pambatalan mirunggan panyedhiya kedah dipuntingali nalika ndhaptar. Tagihan uji coba lumantar Stripe.",
  "settings.cancelTerms.paymentTitle": "Cara pembayaran lan pembaruan otomatis:",
  "settings.cancelTerms.remainingBody": "Menawi Panjenengan sampun mbayar kangge satunggal mangsa tagihan, Panjenengan saged tetep gadhah akses ngantos tanggal bayar ingkang dipunverifikasi punika. Pangendhegan langkung rumiyin mbetahaken konfirmasi panyedhiya ingkang trep lan penanganan wangsulan dana ingkang lumaku. Akses uji coba gratis pungkasan miturut tanggal pangendhegan uji coba ingkang dipunmesthiaken panyedhiya.",
  "settings.cancelTerms.remainingTitle": "Akses ingkang kantun:",
  "settings.cancelTerms.storesBody": "Menawi Panjenengan nate langganan lumantar Google Play utawi Apple App Store, langganan Panjenengan dipuntagih lan dipunkelola dening toko punika. Panjenengan saged prelu mbatalaken langsung ing perangan langganan akun Google utawi Apple ingkang sami ingkang dipunginakaken kangge langganan. Mbatalaken langganan situs web kapisah, mbusak aplikasi punika, utawi nyuwun pambusakan akun Luminous StockHaven mboten kanthi otomatis mbatalaken langganan ingkang dipuntagih toko. Priksa kuitansi tumbas Panjenengan kangge mesthiaken sinten ingkang nagih Panjenengan.",
  "settings.cancelTerms.storesTitle": "Langganan Google Play lan Apple App Store (menawi Panjenengan nate langganan lumantar toko):",
  "settings.cancelTerms.title": "Sarat & Ketentuan Pambatalan",
  "settings.cancelTerms.trialBody": "Uji coba pitung dinten namung saged dipunginakaken satunggal wekdal saben pelanggan ingkang layak. Mbatalaken uji coba utawi langganan mboten maringi uji coba sanès; pelanggan ingkang wangsul kedah milih langganan bayar.",
  "settings.cancelTerms.trialTitle": "Satunggal uji coba gratis:",
  "settings.canceled.endsOn": "Langganan punika dipumbatalaken lan pungkasan ing {date}. Panjenengan tetep gadhah akses jangkep ngantos wekdal punika.",
  "settings.delete.checking": "Mriksa panyuwunan pambusakan ingkang sampun wonten…",
  "settings.delete.description": "Nyuwun pambusakan akun mlebet Luminous StockHaven Panjenengan.",
  "settings.delete.dialogDescription": "Punika nyuwun priksa pambusakan akun. Mboten langsung mbusak mlebet utawi inventaris Panjenengan, lan mboten mbatalaken langganan Stripe punapa kemawon. Ketik {word} kangge mesthiaken Panjenengan kepengin ngintun panyuwunan.",
  "settings.delete.dialogTitle": "Nyuwun Pambusakan Akun",
  "settings.delete.enterDelete": "Lebetaken {word} kangge mesthiaken",
  "settings.delete.exportFirst": "Ekspor inventaris Panjenengan rumiyin menawi Panjenengan mbetahaken njagi cathetan Panjenengan.",
  "settings.delete.intro": "Ngintun panyuwunan mboten langsung mbusak akun, bisnis, utawi inventaris Panjenengan. Panyuwunan dipunpriksa kapisah sadèrèngipun pambusakan saged dipunrampungaken. Panyuwunan punika mboten mbatalaken langganan Stripe utawi mungkasi tagihan mangsa ngajeng; pambatalan langganan kedah dipunurus kapisah lumantar panyedhiya tagihan.",
  "settings.delete.keepAccount": "Tetepaken Akun",
