  "settings.trial.cancelKeeps": "Mbatalaken nalika uji coba njagi 7 dinten Panjenengan jangkep — akses pungkasan ing {date}, lan Panjenengan mboten badhé dipuntagih.",
  "staff.access.noSeatBody": "Akun Panjenengan mboten gadhah kursi staf kangge bisnis punika, dados stokipun tetep katutup. Nyuwun pemilik nambah Panjenengan ing Staf & peran.",
  "staff.access.noSeatTitle": "Bisnis punika mboten mbikak kangge mlebet Panjenengan",
  "staff.access.pendingBody": "Bisnis punika gadhah undhangan kangge email Panjenengan ingkang dereng dipunaktifaken. Nyuwun pemilik nemtokaken status staf Panjenengan dados aktif. Mboten wonten ing ngriki ingkang katon ngantos wekdal punika.",
  "staff.access.pendingTitle": "Undhangan Panjenengan dereng aktif",
  "staff.access.signOut": "Medal",
  "staff.access.suspendedBody": "Administrator sampun nanggellaken akun staf punika kangge bisnis aktif. Nyuwun piyambakipun nemtokaken Panjenengan wangsul dados aktif, lajeng mlebet malih.",
  "staff.access.suspendedTitle": "Akses Panjenengan dipulerenaken",
  "staff.addFirst": "Tambah anggota staf sepisan",
  "staff.addMember": "Tambah anggota staf",
  "staff.emptyBody": "Tambah tiyang, paringi peran lan ijin ingkang sesarengan, lan piyambakipun dipunundang lumantar email kangge mlebet dhateng bisnis punika.",
  "staff.emptyTitle": "Dereng wonten staf",
  "staff.eyebrow": "Tim",
  "staff.how.p1": "Saben anggota gadhah peran lan dhaptar ijin piyambak, dados Panjenengan saged wiwit saking peran lan ngowahi satunggal perkawis tanpa damel peran enggal. Ngowahi peran mboten nyerat malih anggota ingkang sampun wonten ing peran punika — bikak anggota kangge nerapaken malih standar peranipun.",
  "staff.how.p2": "Peran khusus minangka fitur Business: Essentials ngginakaken gangsal peran bawaan (Pemilik, Manajer, Petugas stok, Petugas sadean, Pamriksa).",
  "staff.how.p3": "Undhangan dipunkintun lumantar email. Anggota namung saged mlebet nalika sampun nampi, lan mbusak tiyang saking dhaptar punika mboten mbusak akun aplikasi piyambakipun.",
  "staff.how.p4": "Toko inggih punika lokasi ingkang tiyang dipuntugasi. Kacathet ing kertu piyambakipun; punapa ingkang saged dipunbikak taksih dipuntemtokaken dening peran lan ijinipun.",
  "staff.how.p5": "Ijin nemtokaken punapa ingkang saged dipunbikak saben tiyang: barang menu ing njawi peranipun dipunsingidaken, lan alamat ingkang dipunblokir ningali wara-wara “mboten ing peran Panjenengan” tinimbang kaca. Pangowahan lumaku nalika tiyang punika ngemot aplikasi salajengipun; nanggellaken anggota ngunci piyambakipun medal babar pisan.",
  "staff.how.p6": "Administrator saged mirsani lan ngowahi sedaya data, ngatur panganggo aplikasi lan peran, lan mboten nate kawates dening peran staf. Tiyang tanpa cathetan staf — pemilik bisnis enggal — tetep gadhah akses jangkep.",
  "staff.howTitle": "Kados pundi staf lan peran makarya",
