  "payroll.dd.savings": "Tabungan",
  "payroll.dd.steps.body": "1. Panjenengan mbetahaken rekening bank bisnis ingkang saged ngintun pembayaran ACH. 2. Kempalaken formulir wewenang ingkang sampun dipuntapak asmani saking saben anggota tim — cek ingkang dipunbatalaken mbiyantu mesthiaken nomeripun. 3. Kintun penggajian 2-3 dinten makarya sadèrèngipun dinten gajian supados arta dhateng kanthi tepat wancinipun. 4. Kathah negara bagian mbetahaken idin seratan saking anggota tim. Aplikasi punika ngempalaken formulir lan nuntun Panjenengan nglangkungi langkah-langkahipun — ngintun arta saestu dipunlampahi lumantar bank Panjenengan piyambak.",
