  "training.warningSentOn": "Pangemut kakintun {date}",
  "auth.sameEmailNotice": "Sampun gadhah aplikasi kula saking Google Play utawi App Store? Ginakaken email ingkang sami ing ngriki — email ingkang Panjenengan ginakaken kangge mlebet dhateng aplikasi — supados toko lan inventaris Panjenengan ndherek Panjenengan. Email ingkang beda miwiti toko enggal ingkang kothong babar pisan.",
  "settings.deleteConfirmWord": "BUSEK",
