  "workforce.tab.rewards": "Ganjaran",
  "training.lessons.mgr-give-rewards.step1": "Bikak Tenaga Kerja lan tutul Ganjaran. Pilih anggota tim, lajeng jinisipun: persen potongan ing toko, kertu hadiah, utawi sanesipun ingkang Panjenengan jlentrehaaken kanthi tembung Panjenengan piyambak.",
  "training.lessons.mgr-give-rewards.step2": "Paringi ganjaran nama cekak lan cathetan menawi Panjenengan kersa. Tiyang punika nampi lonceng langsung, lan ganjaran ngentosi ing Ganjaran kula kagunganipun kanthi kode piyambak.",
  "training.lessons.mgr-give-rewards.step3": "Watesipun, miturut desain: Panjenengan maringi ganjaran namung dhateng STAF. Panjenengan mboten saged maringi ganjaran dhateng Panjenengan piyambak utawi manajer sanes — maringi ganjaran dhateng manajer inggih punika putusanipun ingkang gadhah, lan aplikasi badhé nampik kanthi cetha.",
  "training.lessons.mgr-give-rewards.step4": "Ing kasir, ketik kode ingkang dipuntedahaken anggota tim lan tandhani sampun dipunginakaken — saben kode makarya sepisan. Panjenengan saged mbatalaken ganjaran ingkang Panjenengan paringaken menawi rencana ewah; hadiah kagunganipun ingkang gadhah namung ingkang gadhah ingkang saged mbatalaken.",
  "training.lessons.mgr-give-rewards.title": "Maringi ganjaran dhateng staf Panjenengan",
  "training.lessons.owner-give-rewards.step1": "Ganjaran manggen ing Tenaga Kerja, ing tab Ganjaran, lan namung kangge paket Business — ing Essentials tab nedahaken lawang kakunci, dados tim Panjenengan saged mirsani punapa ingkang dipunemot paket ingkang langkung ageng.",
  "training.lessons.owner-give-rewards.step2": "Panjenengan saged maringi ganjaran dhateng SINTEN KEMAWON ing tim — staf lan manajer sami. Pilih tiyangipun, lajeng jinisipun: persen potongan ing toko (persen punapa kemawon ingkang Panjenengan pilih), kertu hadiah dhateng pundi kemawon, utawi insentif punapa kemawon ingkang Panjenengan jlentrehaaken kanthi tembung Panjenengan piyambak.",
  "training.lessons.owner-give-rewards.step3": "Ganjaran dhateng kanthi kode sepisan piyambak lan ngunèkaken lonceng tiyang punika. Piyambakipun nedahaken kode ing kasir; ingkang gadhah utawi manajer ngetik kangge nandhani sampun dipunginakaken.",
  "training.lessons.owner-give-rewards.step4": "Slip ganjaran ingkang kacithak utawi kaandum namung ngemot nama bisnis PANJENENGAN — mboten nate nama aplikasi. Punika matur nuwun toko Panjenengan, sanes iklan.",
  "training.lessons.owner-give-rewards.title": "Maringi ganjaran (paket Business)",
  "training.lessons.owner-rewards-oversight.step1": "Manajer Panjenengan ugi saged maringi ganjaran — namung dhateng staf. Aplikasi nampik manajer maringi ganjaran dhateng piyambakipun piyambak utawi manajer sanes; maringi ganjaran dhateng manajer tansah putusan Panjenengan.",
  "training.lessons.owner-rewards-oversight.step2": "Panjenengan mirsani saben ganjaran ing bisnis ing Riwayat ganjaran: sinten ingkang maringi, sinten ingkang nampi, lan punapa cumawis, sampun dipunginakaken, utawi batal. Manajer namung mirsani ganjaran ingkang dipunparingaken lan ingkang dipuntampi.",
  "training.lessons.owner-rewards-oversight.step3": "Panjenengan saged mbatalaken ganjaran punapa kemawon, kalebet ingkang dipunparingaken manajer Panjenengan. Manajer saged mbatalaken hadiah piyambak, nanging mboten nate kagungan Panjenengan.",
  "training.lessons.owner-rewards-oversight.step4": "Saben kode makarya persis sepisan, lan ganjaran ingkang kabatalaken mboten nate saged dipunginakaken — riwayat tansah nedahaken kadospundi ganjaran pungkasan.",
  "training.lessons.owner-rewards-oversight.title": "Ngawasi ganjaran: paringanipun manajer Panjenengan",
  "training.lessons.staff-your-rewards.step1": "Nalika manajer utawi ingkang gadhah maringi ganjaran dhateng Panjenengan, lonceng Panjenengan muni. Bikak Tenaga Kerja lan tutul Ganjaran kangge mirsani ing ngandhap Ganjaran kula.",
  "training.lessons.staff-your-rewards.step2": "Saben ganjaran gadhah kode piyambak. Jagi kangge Panjenengan piyambak — sinten ingkang nedahaken kode ing kasir inggih punika ingkang ngginakaken ganjaran.",
  "training.lessons.staff-your-rewards.step3": "Kangge ngginakaken, tedahaken kode nalika Panjenengan tumbas. Tiyang ing kasir ngetik lan nandhani sampun dipunginakaken — saben kode makarya persis sepisan.",
  "training.lessons.staff-your-rewards.step4": "Ganjaran inggih punika suguhan paket Business. Menawi toko Panjenengan mboten ing Business, tab Ganjaran nedahaken lawang kakunci kemawon — punika rencananipun, sanes kalepatan.",
  "training.lessons.staff-your-rewards.title": "Ganjaran Panjenengan: manggihi kode Panjenengan lan ngginakaken",
  "training.module.rewards": "Ganjaran & insentif",
