  "pricing.sectionTitle": "Rega obral",
  "pricing.startLabel": "Wiwit",
  "training.lessons.mgr-pricing.step1": "Ing Business, formulir produk duwé bagéan Rega obral. Obral entek panurunan permanèn — gawé lan bakal tetep ana. Rollback yaiku obral nganggo tanggal: gawé rega rollback, dina wiwitané lan dina rampungé.",
  "training.lessons.mgr-pricing.step2": "Sampeyan ora tau kudu ngetik manèh rega lumrah: tetep ana ing produk lan katon ing sandhingé rega adol ing dhaptar produk lan ing pamindai, supaya sapa waé bisa ndeleng rega lumrahé barang kuwi.",
  "training.lessons.mgr-pricing.step3": "Cithaka label rega anyar nalika rollback wiwit — label nyithak rega sing dibayar pelanggan ing dina kuwi. Nalika tanggal rampungé kliwat, regané bali menyang lumrah dhéwé; cithak manèh label lumrah nalika sampeyan nyegeraké rak.",
  "training.lessons.mgr-pricing.step4": "Yèn bagéan Rega obral katon kakunci, bisnis kuwi ora ana ing paket Business — rega obral duwèké paket kuwi, lan sing duwé sing ngganti paket.",
  "training.lessons.mgr-pricing.title": "Nglakokaké obral: obral entek lan rollback",
  "training.lessons.owner-pricing.step1": "Rong jinis panurunan ana ing formulir produk, ing sangisoré Rega obral. Obral entek permanèn: gawéa rega obral entek lan bakal tetep cendhèk nganti sampeyan ngganti manèh. Rollback yaiku obral sauntara — rega sing luwih cendhèk nganggo tanggal wiwitan lan tanggal rampung, kaya obral sing wis sampeyan kenal saka toko-toko gedhé.",
  "training.lessons.owner-pricing.step2": "Rega lumrah ora tau dibusak. Nalika rollback lumaku, aplikasi nuduhaké rega adol bareng rega lumrah ing sandhingé, lan label sing dicithak nggawa rega adol, supaya rak cocog karo kasir.",
  "training.lessons.owner-pricing.step3": "Nalika tanggal rampungé kliwat, regané bali menyang lumrah dhéwé — ora ana sing kudu dielingi, ora ana sing kudu dibatalaké. Rollback sing durung wiwit nyebut tanggal wiwitané, langsung ing dhaptar produk.",
  "training.lessons.owner-pricing.step4": "Rega obral minangka fitur paket Business. Ing Essentials kolom-kolomé tetep kakunci, lan yèn sawijining bisnis mudhun menyang Essentials banjur bali, setelan obral entek lan rollbacké isih ana, persis kaya sing ditinggal.",
  "training.lessons.owner-pricing.title": "Rega obral entek lan rollback (paket Business)",
  "plansLib.includes.shippingLabels": "Label pangiriman 4×6 kanggo pesenan pelanggan",
  "print.templateShipping": "Label pangiriman",
  "print.templateShippingHint": "Label 4×6 nganggo jeneng lan alamaté panuku",
  "print.shipFrom": "Saka",
  "print.recipientNameLabel": "Jenengé panampa",
  "print.recipientAddressLabel": "Alamaté panampa",
  "print.senderAddressLabel": "Alamaté sampeyan (pangirim)",
  "print.shippingNote": "Alamat diketik nalika nyithak lan ora disimpen. Jenengé panampa diisi saka pesenan.",
  "training.lessons.owner-shipping-labels.step1": "Pusat Cithak duwe gaya Label pangiriman ing kaloro paket: piliha pesenan pelanggan lan cithaka label 4×6 nganggo jeneng lan alamaté panuku lan bisnis sampeyan minangka pangirim.",
  "training.lessons.owner-shipping-labels.step2": "Label iki putih, kaya saben dokumen pelanggan: mung nggawa jenengé bisnis sampeyan — ora tau jenengé aplikasi iki — supaya bungkusan saka toko sampeyan katon kaya asale saka toko sampeyan.",
  "training.lessons.owner-shipping-labels.step3": "Pesenan ora nyimpen alamat pos, mula alamat diketik nalika nyithak lan ora disimpen. Mangkono alamat pelanggan tetep ana ing njaba aplikasi babar blas; jenenge tetep diisi saka pesenan supaya label cocog karo kertas-kertase.",
  "training.lessons.owner-shipping-labels.step4": "Label iki dicithak liwat papat sambungan sing padha karo saben label — Bluetooth, Wi-Fi, Ethernet lan USB — lan printer termal 4×6 ukuran biasane.",
  "training.lessons.owner-shipping-labels.title": "Label pangiriman kanggo pesenan pelanggan",
  "training.lessons.print-shipping-label.step1": "Nalika pesenan wis siyap dikirim, bukaka Pusat Cithak, piliha gaya Label pangiriman, banjur piliha pesenan pelanggan. Jenengé panuku diisi saka pesenan.",
  "training.lessons.print-shipping-label.step2": "Ketika alamat sing dituju bungkusane. Alamat diketik nalika nyithak lan ora tau disimpen ing aplikasi, mula priksa kode pos lan baris pungkasan kanthi tliti sadurunge nyithak.",
  "training.lessons.print-shipping-label.step3": "Jenengé bisnis sampeyan dicithak ing dhuwur minangka pangirim. Yen sampeyan pengin alamat sampeyan uga ana ing label, ketika ing kothak alamat pangirim; ninggalna kosong yen sampeyan ora pengin katon.",
  "training.lessons.print-shipping-label.step4": "Cithaka ing label 4×6 — printer label termal pilihan sing lumrah — utawa ing printer apa wae liwat tombol cithak browser. Tempelna label rata ing bungkusan, ing panggonan sing ora bakal dilempit ing pinggir.",
  "training.lessons.print-shipping-label.title": "Nyithak label pangiriman",
  "pos.provider.clover": "Clover",
  "pos.provider.toast": "Toast",
